from abc import ABC, abstractmethod


class Handler(ABC):
    @abstractmethod
    def handle(self, req): ...


class Router:
    def __init__(self):
        self._routes = {}

    def route(self, method, path):
        def decorator(fn):
            self._routes[(method, path)] = fn
            return fn
        return decorator

    def resolve(self, req):
        handler = self._routes.get((req.method, req.path))
        if handler is None:
            return 404
        return handler(req)


